def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find contiguous non-background runs on the four borders.
    def runs(cells):
        result = []
        i = 0
        while i < len(cells):
            color = cells[i]
            if color == bg:
                i += 1
                continue
            j = i + 1
            while j < len(cells) and cells[j] == color:
                j += 1
            result.append((i, j, color))
            i = j
        return result

    edges = {
        'top': runs(grid[0]),
        'bottom': runs(grid[-1]),
        'left': runs([grid[r][0] for r in range(h)]),
        'right': runs([grid[r][-1] for r in range(h)]),
    }
    pairs = [('top', 'bottom'), ('left', 'right')]
    found = None
    for a, b in pairs:
        for ra in edges[a]:
            for rb in edges[b]:
                if ra[2] == rb[2] and (ra[1]-ra[0]) == (rb[1]-rb[0]):
                    found = (a, ra, b, rb)
                    break
            if found: break
        if found: break
    if found is None:
        return out

    a, ra, b, rb = found
    horizontal = a in ('top', 'bottom')
    if horizontal:
        n1, n2 = w, h
    else:
        n1, n2 = h, w
    # All non-background cells other than the two edge bars are marker pixels.
    bars = set()
    for edge, run in ((a, ra), (b, rb)):
        lo, hi, col = run
        if edge == 'top': bars.update((0, x) for x in range(lo, hi))
        elif edge == 'bottom': bars.update((h-1, x) for x in range(lo, hi))
        elif edge == 'left': bars.update((x, 0) for x in range(lo, hi))
        else: bars.update((x, w-1) for x in range(lo, hi))

    lo1, hi1, _ = ra
    lo2, hi2, _ = rb
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in bars:
                continue
            pos = c if horizontal else r
            if lo1 <= pos < hi1:
                source_edge, source_run, target_edge, target_run = a, ra, b, rb
            elif lo2 <= pos < hi2:
                source_edge, source_run, target_edge, target_run = b, rb, a, ra
            else:
                continue
            offset = pos - source_run[0]
            projected = target_run[0] + offset
            # Ray from this marker toward its aligned edge bar (not through it).
            if source_edge == 'top':
                for rr in range(r-1, -1, -1): out[rr][c] = color
            elif source_edge == 'bottom':
                for rr in range(r+1, h): out[rr][c] = color
            elif source_edge == 'left':
                for cc in range(c-1, -1, -1): out[r][cc] = color
            else:
                for cc in range(c+1, w): out[r][cc] = color
            # Matching ray projected from the opposite edge, across the grid.
            if target_edge == 'top':
                for rr in range(1, h): out[rr][projected] = color
            elif target_edge == 'bottom':
                for rr in range(0, h-1): out[rr][projected] = color
            elif target_edge == 'left':
                for cc in range(1, w): out[projected][cc] = color
            else:
                for cc in range(0, w-1): out[projected][cc] = color
            out[r][c] = 4
    return out
